        </thead>
        <tbody>
          {rows.map((row, i) => (
            <tr key={i} className="even:bg-muted/30">
              {table.columns.map((c) => (
                <td
                  key={c}
                  className="truncate border-b border-border/60 px-2 py-1 tabular-nums"
                >
                  {formatCell(row[c] ?? "")}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

